    /// <summary>Gets the catalog string of <paramref name="displayUnitType"/>.</summary>
    public static bool TryGetCatalogString(this DisplayUnitType displayUnitType, [MaybeNullWhen(false)] out string catalogString) =>
        Catalog.TryGetValue(displayUnitType, out catalogString);

    /// <summary>Finds the first display unit whose catalog string equals <paramref name="catalogString"/>, ignoring case; otherwise <see cref="DisplayUnitType.DUT_UNDEFINED"/>.</summary>
    public static bool TryGetFromCatalogString(this string catalogString, out DisplayUnitType displayUnitType)
    {
        foreach (var kv in Catalog)
        {
            if (kv.Value.Equals(catalogString, StringComparison.OrdinalIgnoreCase))
            {
                displayUnitType = kv.Key;
                return true;
            }
        }
        displayUnitType = DisplayUnitType.DUT_UNDEFINED;
        return false;
    }

    /// <summary>Gets the unit types measured by <paramref name="displayUnitType"/>.</summary>
    public static bool TryGetUnitType(this DisplayUnitType displayUnitType, [MaybeNullWhen(false)] out List<UnitType> unitType) =>
        UnitTypes.TryGetValue(displayUnitType, out unitType);

    /// <summary>Gets the display units that measure <paramref name="unitType"/>; the list is empty when there are none.</summary>
    public static bool TryGetDisplayForUnitType(this UnitType unitType, out List<DisplayUnitType> displayUnitTypes)
    {
        displayUnitTypes = UnitTypes.Where(kv => kv.Value.Contains(unitType)).Select(kv => kv.Key).ToList();
        return displayUnitTypes.Count > 0;
    }

    /// <summary>Gets the display units usable for <paramref name="parameterType"/>; the list is empty when there are none.</summary>
    public static bool TryGetDisplayForParameterType(this ParameterType parameterType, out List<DisplayUnitType> displayUnitTypes)
    {
        displayUnitTypes = ParameterTypes.Where(kv => kv.Value.Contains(parameterType)).Select(kv => kv.Key).ToList();
        return displayUnitTypes.Count > 0;
    }

    /// <summary>Gets the unit symbols of <paramref name="displayUnitType"/>.</summary>
    public static bool TryGetUnitSymbolType(this DisplayUnitType displayUnitType, [MaybeNullWhen(false)] out List<UnitSymbolType> unitSymbolType) =>
        Symbols.TryGetValue(displayUnitType, out unitSymbolType);

    /// <summary>Finds the display unit for a symbol text (see <see cref="UnitSymbolTypeExtensions.TryGetFromSymbol"/>); otherwise <see cref="DisplayUnitType.DUT_UNDEFINED"/>.</summary>
    public static bool TryGetFromUnitSymbol(this string unitSymbol, out DisplayUnitType displayUnitType)
    {
        displayUnitType = DisplayUnitType.DUT_UNDEFINED;
        return unitSymbol.TryGetFromSymbol(out var unitSymbolType) && unitSymbolType.TryGetFromUnitSymbol(out displayUnitType);
    }

    /// <summary>Finds the first display unit that lists <paramref name="unitSymbolType"/>; otherwise <see cref="DisplayUnitType.DUT_UNDEFINED"/>.</summary>
    public static bool TryGetFromUnitSymbol(this UnitSymbolType unitSymbolType, out DisplayUnitType displayUnitType)
    {
        foreach (var kv in Symbols)
        {
            if (kv.Value.Contains(unitSymbolType))
            {
                displayUnitType = kv.Key;
                return true;
            }
        }
        displayUnitType = DisplayUnitType.DUT_UNDEFINED;
        return false;
    }
}
